mapper.select:
select count(1)
from ai_credit_batch
where user_id = #{userId}
  and source_type = #{sourceType}
  and source_id = #{sourceId}

select count(1)
from ai_credit_record
where user_id = #{userId}
  and change_type = #{changeType}
  and related_type = #{relatedType}
  and related_id = #{relatedId}

mapper.insert:
insert into ai_credit_batch(
    user_id, source_type, source_id, total_amount, remaining_amount, expire_time, remark, create_time
) values (
    #{userId}, #{sourceType}, #{sourceId}, #{totalAmount}, #{remainingAmount}, #{expireTime}, #{remark}, sysdate()
)

mapper.update:
update ai_credit_batch
set remaining_amount = remaining_amount - #{amount},
    update_time = sysdate()
where batch_id = #{batchId}
  and remaining_amount >= #{amount}

mapper.insert:
insert into ai_credit_record(
    user_id, change_type, amount, balance_after, related_type, related_id, remark, create_time
) values (
    #{userId}, #{changeType}, #{amount}, #{balanceAfter}, #{relatedType}, #{relatedId}, #{remark}, sysdate()
)

mapper.select:
select record_id, user_id, change_type, amount, balance_after, related_type, related_id, remark, create_time
from ai_credit_record
where user_id = #{userId}
order by create_time desc, record_id desc
limit #{limit}
